package com.nexushr.service; import com.nexushr.dto.RequestDtos.PerformanceRequest; import com.nexushr.entity.*; import com.nexushr.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PerformanceService {final PerformanceReviewRepository repo;final EmployeeService emp;public PerformanceService(PerformanceReviewRepository r,EmployeeService e){repo=r;emp=e;} public List<PerformanceReview> mine(String email){return repo.findByEmployeeIdOrderByReviewYearDesc(emp.current(email).getId());} public PerformanceReview create(UUID id,PerformanceRequest x){var p=new PerformanceReview();p.setEmployee(emp.employees.findById(id).orElseThrow());p.setReviewYear(x.reviewYear());p.setRating(x.rating());p.setStrengths(x.strengths());p.setImprovementAreas(x.improvementAreas());p.setManagerFeedback(x.managerFeedback());p.setReviewDate(x.reviewDate());return repo.save(p);}}
